{"security_risk":"LOW","summary":"Create rust-src directory","command":"create","path":"/workspace/codebase/rust-src/main.rs","file_text":"mod args;
mod discover;
mod help;
mod ignore;
mod runner;

use std::process::ExitCode;

fn main() -> ExitCode {
    match run() {
        Ok(code) => code.into(),
        Err(err) => {
            // Mirror the original CLI behavior: print message and exit
            // using the exit code attached to the error (default 1).
            let exit_code = err.exit_code();
            let stream = if exit_code == 0 {
                std::io::stdout()
            } else {
                std::io::stderr()
            };
            use std::io::Write;
            let _ = writeln!(stream, "{}", err.message());
            exit_code.into()
        }
    }
}

fn run() -> Result<args::ExitOutcome, CliError> {
    // Pull the raw arguments from the environment, skipping argv[0].
    let raw_args: Vec<String> = std::env::args().skip(1).collect();

    // Parse them with the JS-compatible parser.
    let parsed = args::parse(&raw_args)?;
    if let Some(out) = parsed.immediate_exit {
        return Ok(out);
    }

    let mut opts = parsed.options;
    let positional = parsed.positional;

    // No paths and not stdin → error.
    if positional.is_empty() && !opts.stdin {
        let msg = format!(
            "Error: You have to provide at least one file/directory to transform.\n\n---\n\n{}",
            help::help_text()
        );
        return Err(CliError::with_code(1, msg));
    }

    // Build the final option set that we forward to the JS workers.
    opts.finalize();

    // Collect the file list.
    let mut paths = positional;
    if opts.stdin {
        use std::io::BufRead;
        let stdin = std::io::stdin();
        for line in stdin.lock().lines() {
            let line = line?;
            if line.is_empty() {
                continue;
            }
            paths.push(line);
        }
    }

    // Handle transform URL download (http(s)) → write to a temp file.
    let transform_path = if opts.transform.starts_with("http://")
        || opts.transform.starts_with("https://")
    {
        match runner::download_transform(&opts.transform) {
            Ok(p) => p,
            Err(e) => {
                eprintln!("Error downloading transform: {}", e);
                return Ok(args::ExitOutcome::Code(1));
            }
        }
    } else {
        opts.transform.clone()
    };

    if !std::path::Path::new(&transform_path).exists() {
        eprintln!(
            "\x1b[41m\x1b[37mERROR\x1b[0m\x1b[0m Transform file {} does not exist",
            transform_path
        );
        return Ok(args::ExitOutcome::Code(1));
    }

    runner::run(transform_path, paths, opts)
}

#[derive(Debug)]
pub struct CliError {
    code: i32,
    msg: String,
}

impl CliError {
    pub fn with_code(code: i32, msg: String) -> Self {
        CliError { code, msg }
    }
    pub fn exit_code(&self) -> i32 {
        self.code
    }
    pub fn message(&self) -> &str {
        &self.msg
    }
}

impl From<String> for CliError {
    fn from(msg: String) -> Self {
        CliError::with_code(1, msg)
    }
}

impl From<&str> for CliError {
    fn from(msg: &str) -> Self {
        CliError::with_code(1, msg.to_string())
    }
}

impl From<std::io::Error> for CliError {
    fn from(e: std::io::Error) -> Self {
        CliError::with_code(1, format!("{}", e))
    }
}"}

{"security_risk":"LOW","summary":"Create args.rs","command":"create","path":"/workspace/codebase/rust-src/args.rs","file_text":"//! JS-compatible argument parser.
//!
//! The original jscodeshift CLI uses a hand-rolled argument parser in
//! `src/argsParser.js`. We reproduce its observable behavior in Rust:
//!
//!   - Options are declared in a table with a "display index" that controls
//!     the order of the generated help text.
//!   - `--flag` style options take no value. `--no-foo` sets the value to
//!     `false`.
//!   - Options without a flag consume the next argument as a value (unless
//!     it starts with `-`).
//!   - `=value` syntax is supported.
//!   - Unknown options are recorded in a generic bag and may collect
//!     multiple values.
//!   - The `version` option triggers an immediate exit with version info.
//!   - The `help` option triggers an immediate exit with help text.

use crate::help;
use crate::CliError;

#[derive(Debug, Clone)]
pub struct ParsedArgs {
    pub options: Options,
    pub positional: Vec<String>,
    pub immediate_exit: Option<ExitOutcome>,
}

#[derive(Debug, Clone)]
pub enum ExitOutcome {
    Code(i32),
}

/// Final bag of parsed options that we forward to the JS worker.
///
/// This is the exact set of values that the JS Worker expects to receive in
/// its `data.options` payload. Anything else would break compatibility.
#[derive(Debug, Clone)]
pub struct Options {
    pub transform: String,
    pub cpus: Option<usize>,
    pub verbose: u8,
    pub dry: bool,
    pub print: bool,
    pub babel: bool,
    pub extensions: Option<String>,
    pub ignore_pattern: Vec<String>,
    pub ignore_config: Vec<String>,
    pub gitignore: bool,
    pub run_in_band: bool,
    pub silent: bool,
    pub parser: String,
    pub parser_config: Option<String>,
    pub fail_on_error: bool,
    pub stdin: bool,
    /// Extra options captured verbatim from the CLI. These are forwarded to
    /// the transform as `options.<key>`.
    pub extra: Vec<(String, ExtraValue)>,
}

#[derive(Debug, Clone)]
pub enum ExtraValue {
    Flag(bool),
    Value(String),
    List(Vec<String>),
}

impl Options {
    pub fn finalize(&mut self) {
        if self.cpus.is_none() {
            self.cpus = Some(default_cpus());
        }
        if self.extensions.is_none() {
            self.extensions = Some(default_extensions());
        }
    }

    /// Serialize to JSON the way the JS worker expects it.
    pub fn to_json(&self) -> serde_json::Value {
        use serde_json::json;
        let mut obj = json!({
            "transform": self.transform,
            "cpus": self.cpus,
            "verbose": self.verbose,
            "dry": self.dry,
            "print": self.print,
            "babel": self.babel,
            "extensions": self.extensions,
            "ignorePattern": self.ignore_pattern,
            "ignoreConfig": self.ignore_config,
            "gitignore": self.gitignore,
            "runInBand": self.run_in_band,
            "silent": self.silent,
            "parser": self.parser,
            "parserConfig": self.parser_config,
            "failOnError": self.fail_on_error,
            "stdin": self.stdin,
        });
        let map = obj.as_object_mut().unwrap();
        for (k, v) in &self.extra {
            map.insert(
                k.clone(),
                match v {
                    ExtraValue::Flag(b) => serde_json::Value::Bool(*b),
                    ExtraValue::Value(s) => serde_json::Value::String(s.clone()),
                    ExtraValue::List(items) => serde_json::Value::Array(
                        items
                            .iter()
                            .map(|s| serde_json::Value::String(s.clone()))
                            .collect(),
                    ),
                },
            );
        }
        obj
    }
}

pub fn default_extensions() -> String {
    // Babel 7's DEFAULT_EXTENSIONS plus "ts" and "tsx", stripped of leading
    // dots, sorted and joined with commas.
    let mut exts = vec![
        "cjs", "es", "es6", "js", "jsx", "mjs", "ts", "tsx",
    ];
    exts.sort();
    exts.dedup();
    exts.join(",")
}

pub fn default_cpus() -> usize {
    let cpus = std::thread::available_parallelism()
        .map(|n| n.get())
        .unwrap_or(1);
    std::cmp::max(cpus.saturating_sub(1), 1)
}

pub fn parse(args: &[String]) -> Result<ParsedArgs, CliError> {
    // Pre-process: collect raw option/positional strings.
    let mut positional: Vec<String> = Vec::new();
    let mut tokens: Vec<Token> = Vec::new();
    let mut i = 0;
    while i < args.len() {
        let a = &args[i];
        if a.starts_with("--") || (a.starts_with('-') && a.len() > 1) {
            if let Some(eq) = a.find('=') {
                let key = a[..eq].to_string();
                let val = a[eq + 1..].to_string();
                tokens.push(Token::OptWithValue(key, val));
            } else {
                tokens.push(Token::Opt(a.clone()));
            }
        } else {
            // Numbers are kept as strings for fidelity with the original.
            positional.push(a.clone());
        }
        i += 1;
    }

    // Walk tokens and produce parsed options.
    let mut parsed = ParsedBuilder::new();

    let mut idx = 0;
    while idx < tokens.len() {
        let tok = tokens[idx].clone();
        match tok {
            Token::Opt(arg) | Token::OptWithValue(arg, _) if arg == "--help" || arg == "-h" => {
                // Immediate exit with help text.
                return Ok(ParsedArgs {
                    options: parsed.build(),
                    positional,
                    immediate_exit: Some(ExitOutcome::Code(0)),
                });
            }
            Token::Opt(arg) | Token::OptWithValue(arg, _) if arg == "--version" => {
                // The version output is special; the JS code prints it on
                // stdout regardless of exit code (because it uses the
                // `callback` branch which doesn't set exitCode=1).
                // We'll return it as a synthetic message via immediate_exit.
                return Ok(ParsedArgs {
                    options: parsed.build(),
                    positional,
                    immediate_exit: Some(ExitOutcome::Code(0)),
                });
            }
            Token::Opt(arg) => {
                let known = known_option(&arg);
                match known {
                    Some(opt) => {
                        // Consume next token as value if needed.
                        let value = if opt.takes_value {
                            if idx + 1 < tokens.len() {
                                if let Token::Opt(ref next) = tokens[idx + 1] {
                                    if next.starts_with('-') {
                                        None
                                    } else {
                                        let v = next.clone();
                                        idx += 1;
                                        Some(Token::Opt(v))
                                    }
                                } else {
                                    None
                                }
                            } else {
                                None
                            }
                        } else {
                            None
                        };
                        parsed.apply(opt, value.as_ref().map(token_to_string));
                    }
                    None => {
                        // Unknown option; figure out flag/list semantics.
                        let real = strip_option_prefix(&arg);
                        let explicit_value =
                            if arg.starts_with("--no-") { Some(false) } else { None };
                        parsed.apply_unknown(
                            &arg,
                            &real,
                            explicit_value,
                            None,
                            idx + 1 < tokens.len()
                                && is_non_option_token(&tokens[idx + 1]),
                        );
                    }
                }
            }
            Token::OptWithValue(arg, value) => {
                let known = known_option(&arg);
                match known {
                    Some(opt) => {
                        let value_str = opt.process(&value);
                        parsed.apply_known_value(opt, value_str);
                    }
                    None => {
                        let real = strip_option_prefix(&arg);
                        let explicit_value =
                            if arg.starts_with("--no-") { Some(false) } else { None };
                        // The original treated this as a single value even if
                        // the option was previously seen.
                        parsed.apply_unknown(
                            &arg,
                            &real,
                            explicit_value,
                            Some(value),
                            false,
                        );
                    }
                }
            }
        }
        idx += 1;
    }

    let options = parsed.build();
    // If --version was the first thing we saw, surface that as immediate_exit.
    if let Some(v) = parsed.pending_immediate.as_ref() {
        return Ok(ParsedArgs {
            options,
            positional,
            immediate_exit: Some(v.clone()),
        });
    }
    Ok(ParsedArgs {
        options,
        positional,
        immediate_exit: None,
    })
}

#[derive(Debug, Clone)]
enum Token {
    Opt(String),
    OptWithValue(String, String),
}

fn token_to_string(t: &Token) -> String {
    match t {
        Token::Opt(s) => s.clone(),
        Token::OptWithValue(_, s) => s.clone(),
    }
}

fn is_non_option_token(t: &Token) -> bool {
    !matches!(t, Token::Opt(s) if s.starts_with('-'))
}

fn strip_option_prefix(arg: &str) -> String {
    // Strip leading "-" or "--", plus optional "no-" prefix.
    let mut s = arg.trim_start_matches('-').to_string();
    if s.starts_with("no-") {
        s = s.trim_start_matches("no-").to_string();
    }
    s
}

