fn known_option(arg: &str) -> Option<KnownOpt> {
    for opt in known_options() {
        if arg == format!("--{}", opt.full) || opt.abbr.map(|a| arg == format!("-{}", a)).unwrap_or(false) {
            return Some(opt);
        }
        // --no-X form for flags
        if opt.flag && arg == format!("--no-{}", opt.full) {
            return Some(opt);
        }
    }
    None
}

impl KnownOpt {
    pub fn process(&self, value: &str) -> String {
        // Match the original nomnom-style JSON parsing for known options.
        // For cpus and verbose we want numbers.
        if self.key == "cpus" || self.key == "verbose" {
            if let Ok(n) = value.parse::<i64>() {
                return n.to_string();
            }
            return value.to_string();
        }
        // Otherwise try JSON parse, fall back to string.
        if let Ok(v) = serde_json::from_str::<serde_json::Value>(value) {
            match v {
                serde_json::Value::String(_) | serde_json::Value::Number(_) | serde_json::Value::Bool(_) => {
                    return match v {
                        serde_json::Value::String(s) => s,
                        serde_json::Value::Number(n) => n.to_string(),
                        serde_json::Value::Bool(b) => b.to_string(),
                        _ => value.to_string(),
                    };
                }
                _ => {}
            }
        }
        value.to_string()
    }
}

#[derive(Default)]
struct ParsedBuilder {
    transform: String,
    cpus: Option<String>,
    verbose: Option<String>,
    dry: Option<bool>,
    print: Option<bool>,
    babel: Option<bool>,
    extensions: Option<String>,
    ignore_pattern: Vec<String>,
    ignore_config: Vec<String>,
    gitignore: Option<bool>,
    run_in_band: Option<bool>,
    silent: Option<bool>,
    parser: Option<String>,
    parser_config: Option<String>,
    fail_on_error: Option<bool>,
    stdin: Option<bool>,
    extra: Vec<(String, ExtraValue)>,
    /// Set when --version was supplied so we can return an immediate exit.
    pending_immediate: Option<ExitOutcome>,
}

impl ParsedBuilder {
    fn new() -> Self {
        // Pre-populate defaults so behavior matches the JS original even
        // when an option was not specified at all.
        let defaults = known_options();
        let mut b = ParsedBuilder::default();
        for opt in defaults {
            if let Some(d) = opt.default {
                let val = match d {
                    DefaultValue::Bool(v) => v.to_string(),
                    DefaultValue::Str(v) => v.to_string(),
                    DefaultValue::Int(v) => v.to_string(),
                };
                b.set_default(opt, val);
            }
        }
        b
    }

    fn set_default(&mut self, opt: KnownOpt, value: String) {
        match opt.key {
            "transform" => self.transform = value,
            "cpus" => self.cpus = Some(value),
            "verbose" => self.verbose = Some(value),
            "dry" => self.dry = Some(value == "true"),
            "print" => self.print = Some(value == "true"),
            "babel" => self.babel = Some(value == "true"),
            "extensions" => self.extensions = Some(value),
            "ignorePattern" => {} // list defaults to []
            "ignoreConfig" => {}  // list defaults to []
            "gitignore" => self.gitignore = Some(value == "true"),
            "runInBand" => self.run_in_band = Some(value == "true"),
            "silent" => self.silent = Some(value == "true"),
            "parser" => self.parser = Some(value),
            "parserConfig" => self.parser_config = Some(value).filter(|s| !s.is_empty()),
            "failOnError" => self.fail_on_error = Some(value == "true"),
            "stdin" => self.stdin = Some(value == "true"),
            "version" => {}
            _ => {}
        }
    }

    fn apply(&mut self, opt: KnownOpt, value: Option<String>) {
        match opt.key {
            "help" => {
                // Already handled above; safety net.
            }
            "version" => {
                self.pending_immediate = Some(ExitOutcome::Code(0));
            }
            "transform" => {
                if let Some(v) = value {
                    self.transform = v;
                }
            }
            "cpus" => {
                if let Some(v) = value {
                    self.cpus = Some(v);
                }
            }
            "verbose" => {
                if let Some(v) = value {
                    self.verbose = Some(v);
                }
            }
            "dry" => {
                self.dry = Some(true);
            }
            "print" => {
                self.print = Some(true);
            }
            "babel" => {
                self.babel = Some(true);
            }
            "extensions" => {
                if let Some(v) = value {
                    self.extensions = Some(v);
                }
            }
            "ignorePattern" => {
                if let Some(v) = value {
                    self.ignore_pattern.push(v);
                }
            }
            "ignoreConfig" => {
                if let Some(v) = value {
                    self.ignore_config.push(v);
                }
            }
            "no-gitignore" => {
                self.gitignore = Some(false);
            }
            "gitignore" => {
                self.gitignore = Some(true);
            }
            "runInBand" => {
                self.run_in_band = Some(true);
            }
            "no-runInBand" => {
                self.run_in_band = Some(false);
            }
            "silent" => {
                self.silent = Some(true);
            }
            "parser" => {
                if let Some(v) = value {
                    self.parser = Some(v);
                }
            }
            "parserConfig" => {
                if let Some(v) = value {
                    self.parser_config = Some(v);
                }
            }
            "failOnError" => {
                self.fail_on_error = Some(true);
            }
            "no-failOnError" => {
                self.fail_on_error = Some(false);
            }
            "stdin" => {
                self.stdin = Some(true);
            }
            _ => {}
        }
    }

    fn apply_known_value(&mut self, opt: KnownOpt, value: String) {
        match opt.key {
            "cpus" => self.cpus = Some(value),
            "verbose" => self.verbose = Some(value),
            "extensions" => self.extensions = Some(value),
            "ignorePattern" => self.ignore_pattern.push(value),
            "ignoreConfig" => self.ignore_config.push(value),
            "transform" => self.transform = value,
            "parser" => self.parser = Some(value),
            "parserConfig" => self.parser_config = Some(value),
            _ => {}
        }
    }

    fn apply_unknown(
        &mut self,
        raw: &str,
        real: &str,
        explicit_false: Option<bool>,
        inline_value: Option<String>,
        next_arg_is_value: bool,
    ) {
        let existing = self
            .extra
            .iter()
            .position(|(k, _)| k == real)
            .map(|i| i);

        let neg_prefix = raw.starts_with("--no-");
        let is_list = existing.is_some()
            && !matches!(self.extra.get(existing.unwrap()).map(|(_, v)| v), Some(ExtraValue::Flag(_)));

        if let Some(idx) = existing {
            // Already seen: convert to list if not already.
            let entry = self.extra[idx].clone();
            if !is_list {
                let new_list = match entry.1 {
                    ExtraValue::Flag(true) => vec![],
                    ExtraValue::Value(v) => vec![v],
                    _ => vec![],
                };
                self.extra[idx].1 = ExtraValue::List(new_list);
            }
            let value = if let Some(v) = inline_value {
                Some(v)
            } else if !neg_prefix && next_arg_is_value {
                None // caller should consume next token
            } else {
                None
            };
            if let Some(v) = value {
                if let ExtraValue::List(ref mut list) = self.extra[idx].1 {
                    list.push(v);
                }
            } else if inline_value.is_none() && neg_prefix {
                // --no-foo with prior presence → just record as flag false
                if let ExtraValue::List(ref mut list) = self.extra[idx].1 {
                    list.clear();
                }
            }
        } else {
            // First occurrence.
            let flag = !neg_prefix && inline_value.is_none() && !next_arg_is_value;
            let value = if let Some(v) = inline_value {
                ExtraValue::Value(v)
            } else if flag {
                if neg_prefix {
                    ExtraValue::Flag(false)
                } else {
                    ExtraValue::Flag(true)
                }
            } else if neg_prefix {
                ExtraValue::Flag(false)
            } else {
                // Will be populated when we consume the next token.
                ExtraValue::Flag(true)
            };
            if let Some(false_v) = explicit_false {
                self.extra.push((real.to_string(), ExtraValue::Flag(false_v)));
            } else {
                self.extra.push((real.to_string(), value));
            }
        }
    }

    fn build(self) -> Options {
        Options {
            transform: self.transform,
            cpus: self.cpus.and_then(|s| s.parse().ok()).or(Some(default_cpus())),
            verbose: self.verbose.and_then(|s| s.parse().ok()).unwrap_or(0),
            dry: self.dry.unwrap_or(false),
            print: self.print.unwrap_or(false),
            babel: self.babel.unwrap_or(true),
            extensions: self.extensions,
            ignore_pattern: self.ignore_pattern,
            ignore_config: self.ignore_config,
            gitignore: self.gitignore.unwrap_or(false),
            run_in_band: self.run_in_band.unwrap_or(false),
            silent: self.silent.unwrap_or(false),
            parser: self.parser.unwrap_or_else(|| "babel".to_string()),
            parser_config: self.parser_config,
            fail_on_error: self.fail_on_error.unwrap_or(false),
            stdin: self.stdin.unwrap_or(false),
            extra: self.extra,
        }
    }
}"}

{"security_risk":"LOW","summary":"Create help.rs","command":"create","path":"/workspace/codebase/rust-src/help.rs","file_text":"//! Help text generation.
//!
//! The text intentionally matches `getHelpText()` from `src/argsParser.js`,
//! preserving the trailing two-space indent, the "Usage" block, and the
//! `(default: ...)` continuation lines.

use crate::args::known_options;

pub fn help_text() -> String {
    let opts = {
        let mut v = known_options();
        v.sort_by_key(|o| o.display_index);
        v
    };

    let mut text = String::new();
    text.push_str("Usage: jscodeshift [OPTION]... PATH...\n");
    text.push_str("  or:  jscodeshift [OPTION]... -t TRANSFORM_PATH PATH...\n");
    text.push_str("  or:  jscodeshift [OPTION]... -t URL PATH...\n");
    text.push_str("  or:  jscodeshift [OPTION]... --stdin < file_list.txt\n");
    text.push('\n');
    text.push_str(
        "Apply transform logic in TRANSFORM_PATH (recursively) to every PATH.\n",
    );
    text.push_str(
        "If --stdin is set, each line of the standard input is used as a path.\n",
    );
    text.push('\n');
    text.push_str("Options:\n");
    text.push_str(
        "\"...\" behind an option means that it can be supplied multiple times.\n",
    );
    text.push_str(
        "All options are also passed to the transformer, which means you can supply custom options that are not listed here.\n",
    );
    text.push('\n');

    for opt in opts {
        text.push_str(&format_option(opt));
        text.push('\n');
    }

    // The JS code trims the leading whitespace.
    text.trim_start().to_string()
}

fn format_option(opt: crate::args::KnownOpt) -> String {
    let mut text = String::new();
    text.push_str("  ");
    if let Some(abbr) = opt.abbr {
        text.push_str(&format!("-{}, ", abbr));
    } else {
        text.push_str("    ");
    }

    if opt.flag {
        text.push_str(&format!("--(no-){}", opt.full));
    } else {
        text.push_str(&format!("--{}", opt.full));
    }

    if !opt.choices.is_empty() {
        text.push_str(&format!("={}", opt.choices.join("|")));
    } else if let Some(metavar) = metavar_for(opt.key) {
        text.push_str(&format!("={}", metavar));
    }

    if opt.list {
        text.push_str(" ...");
    }

    if opt.default_help().is_some() || opt.help().is_some() {
        text.push_str("  ");
        if text.len() < 32 {
            for _ in 0..(32 - text.len()) {
                text.push(' ');
            }
        }
        let text_length = text.len();
        if let Some(h) = opt.help() {
            text.push_str(h);
        }
        if let Some(d) = opt.default_help() {
            if opt.help().is_some() {
                text.push('\n');
            }
            for _ in 0..text_length {
                text.push(' ');
            }
            text.push_str(&format!("(default: {})", d));
        }
    }
    text
}

impl crate::args::KnownOpt {
    fn help(&self) -> Option<&'static str> {
        match self.key {
            "transform" => Some(
                "path to the transform file. Can be either a local path or url",
            ),
            "cpus" => Some("start at most N child processes to process source files"),
            "verbose" => Some("show more information about the transform process"),
            "dry" => Some("dry run (no changes are made to files)"),
            "print" => Some("print transformed files to stdout, useful for development"),
            "babel" => Some("apply babeljs to the transform file"),
            "extensions" => {
                Some("transform files with these file extensions (comma separated list)")
            }
            "ignorePattern" => Some("ignore files that match a provided glob expression"),
            "ignoreConfig" => Some(
                "ignore files if they match patterns sourced from a configuration file (e.g. a .gitignore)",
            ),
            "gitignore" => Some("adds entries the current directory's .gitignore file"),
            "runInBand" => Some("run serially in the current process"),
            "silent" => Some("do not write to stdout or stderr"),
            "parser" => Some("the parser to use for parsing the source files"),
            "parserConfig" => Some(
                "path to a JSON file containing a custom parser configuration for flow or babylon",
            ),
            "failOnError" => Some("Return a non-zero code when there are errors"),
            "stdin" => Some("read file/directory list from stdin"),
            "version" => Some("print version and exit"),
            "help" => Some("print this help and exit"),
            _ => None,
        }
    }

    fn default_help(&self) -> Option<String> {
        match self.key {
            "transform" => Some("./transform.js".to_string()),
            "cpus" => Some("max(all - 1, 1)".to_string()),
            "verbose" => Some("0".to_string()),
            "dry" => Some("false".to_string()),
            "print" => Some("false".to_string()),
            "babel" => Some("true".to_string()),
            "extensions" => Some("cjs,es,es6,js,jsx,mjs,ts,tsx".to_string()),
            "gitignore" => Some("false".to_string()),
            "runInBand" => Some("false".to_string()),
            "silent" => Some("false".to_string()),
            "parser" => Some("babel".to_string()),
            "failOnError" => Some("false".to_string()),
            "stdin" => Some("false".to_string()),
            _ => None,
        }
    }
}

fn metavar_for(key: &str) -> Option<&'static str> {
    match key {
        "transform" => Some("FILE"),
        "cpus" => Some("N"),
        "verbose" => Some("N"),
        "extensions" => Some("EXT"),
        "ignorePattern" => Some("GLOB"),
        "ignoreConfig" => Some("FILE"),
        "parserConfig" => Some("FILE"),
        _ => None,
    }
}

pub fn version_text() -> String {
    use crate::runner;
    let pkg_version = env!("CARGO_PKG_VERSION");
    let babel = runner::package_version("@babel/core");
    let babylon = runner::package_version("@babel/parser");
    let flow = runner::package_version("flow-parser");
    let recast = runner::package_version("recast");
    format!(
        "jscodeshift: {}\n - babel: {}\n - babylon: {}\n - flow: {}\n - recast: {}\n",
        pkg_version, babel, babylon, flow, recast
    )
}"}

{"security_risk":"LOW","summary":"Create ignore.rs","command":"create","path":"/workspace/codebase/rust-src/ignore.rs","file_text":"//! Gitignore-style ignore matching using the `ignore` crate.
//!
//! The semantics of `src/ignoreFiles.js` are:
//!
//!   1. Patterns are compiled and matched against the **relative** path
//!      (because the original code calls `picomatch` with the relative path
//!      as captured during traversal).
//!   2. `**/pattern` is auto-prepended to patterns without a `/`.
//!   3. Patterns ending in `/` are expanded to both `**/<pattern>**` and
//!      `<pattern>**`.
//!   4. Comments and blank lines are skipped.
//!
//! We translate that to `ignore::gitignore::GitignoreBuilder`, which honors
//! gitignore syntax closely enough for our purposes.

use ignore::gitignore::{Gitignore, GitignoreBuilder};
use std::path::Path;

pub struct IgnoreSet {
    inner: Option<Gitignore>,
}

impl IgnoreSet {
    pub fn new() -> Self {
        IgnoreSet { inner: None }
    }

    /// Add patterns from a list of strings.
    pub fn add_patterns(&mut self, patterns: &[String]) {
        let mut b = GitignoreBuilder::new("");
        for p in patterns {
            add_one(&mut b, p);
        }
        match b.build() {
            Ok(g) => self.inner = Some(g),
            Err(_) => self.inner = None,
        }
    }

    /// Add patterns from a config file (.gitignore style).
    pub fn add_file(&mut self, path: &Path) {
        if !path.is_file() {
            return;
        }
        match GitignoreBuilder::new(path.parent().unwrap_or_else(|| Path::new("")))
            .add(path)
            .build()
        {
            Ok(g) => self.inner = Some(g),
            Err(_) => self.inner = None,
        }
    }

    /// Test whether a path should be ignored.
    pub fn is_match<P: AsRef<Path>>(&self, path: P, is_dir: bool) -> bool {
        match &self.inner {
            Some(g) => g
                .matched_path_or_any_parents(path.as_ref(), is_dir)
                .is_ignore(),
            None => false,
        }
    }
}

fn add_one(b: &mut GitignoreBuilder, raw: &str) {
    let trimmed = raw.trim();
    if trimmed.is_empty() || trimmed.starts_with('#') {
        return;
    }
    // Mirror the JS behavior.
    let pattern = if !trimmed.contains('/') {
        format!("**/{}", trimmed)
    } else if trimmed.ends_with('/') {
        // We add two patterns in the JS code; the second one is what
        // matches a rooted directory, and `ignore` handles both cases.
        b.add_line(format!("**/{}/**", trimmed.trim_end_matches('/')));
        format!("{}/**", trimmed.trim_end_matches('/'))
    } else {
        trimmed.to_string()
    };
    b.add_line(&pattern);
}"}

{"security_risk":"LOW","summary":"Create discover.rs","command":"create","path":"/workspace/codebase/rust-src/discover.rs","file_text":"//! File discovery.
//!
//! Mirrors `dirFiles()` and `getAllFiles()` from `src/Runner.js`:
//!
//!   * Each input path is expanded. Directories are walked recursively.
//!   * Each entry is filtered by file extension (if specified) and the
//!     ignore set.
//!   * Symbolic links are not followed (the original uses `fs.lstat`).
//!   * Missing paths produce a stderr message but do not abort.

use crate::ignore::IgnoreSet;
use std::path::{Path, PathBuf};

pub fn collect(paths: &[String], extensions: Option<&str>, ignores: &IgnoreSet) -> Vec<PathBuf> {
    let mut out = Vec::new();
    let ext_set = extensions.map(parse_extensions);
    for p in paths {
        let path = Path::new(p);
        let metadata = match std::fs::symlink_metadata(path) {
            Ok(m) => m,
            Err(_) => {
                eprintln!("Skipping path {} which does not exist.", p);
                continue;
            }
        };
        if metadata.is_dir() {
            walk(path, &mut out, &ext_set, ignores);
        } else if !should_ignore(path, &ext_set, ignores) {
            out.push(path.to_path_buf());
        }
    }
    out
}

fn walk(dir: &Path, out: &mut Vec<PathBuf>, ext: &Option<Vec<String>>, ignores: &IgnoreSet) {
    let entries = match std::fs::read_dir(dir) {
        Ok(e) => e,
        Err(e) => {
            eprintln!("Could not read dir {}: {}", dir.display(), e);
            return;
        }
    };
    for entry in entries.flatten() {
        let path = entry.path();
        let m = match std::fs::symlink_metadata(&path) {
            Ok(m) => m,
            Err(_) => {
                eprintln!("Skipping path {} which does not exist.", path.display());
                continue;
            }
        };
        if ignores.is_match(&path, m.is_dir()) {
            continue;
        }
        if m.is_dir() {
            walk(&path, out, ext, ignores);
        } else if !should_ignore(&path, ext, ignores) {
            out.push(path);
        }
    }
}

fn parse_extensions(spec: &str) -> Vec<String> {
    spec.split(',')
        .map(|s| s.trim())
        .filter(|s| !s.is_empty())
        .map(|s| if s.starts_with('.') { s.to_string() } else { format!(".{}", s) })
        .collect()
}

fn should_ignore(path: &Path, ext: &Option<Vec<String>>, ignores: &IgnoreSet) -> bool {
    if let Some(list) = ext {
        let cur = path
            .extension()
            .and_then(|e| e.to_str())
            .map(|s| format!(".{}", s));
        if !cur.as_ref().map_or(false, |e| list.iter().any(|x| x == e)) {
            return true;
        }
    }
    if ignores.is_match(path, false) {
        return true;
    }
    false
}"}

{"security_risk":"LOW","summary":"Create runner.rs","command":"create","path":"/workspace/codebase/rust-src/runner.rs","file_text":"//! Worker orchestration.
//!
//! This module mirrors the responsibilities of `src/Runner.js` (parent side
//! only — the actual transform execution happens in the Node.js bridge):
//!
//!   * Spawn one Node.js worker process per CPU slot.
//!   * Feed each worker a sequence of file batches via stdin (JSON lines).
//!   * Read status / update / report / free messages from each worker via
//!     stdout (JSON lines).
//!   * Aggregate counters, print formatted logs, and exit with the
//!     `failOnError` semantics when requested.

use crate::args::{ExitOutcome, Options};
use crate::discover;
use crate::ignore::IgnoreSet;
use serde_json::json;
use std::io::{BufRead, BufReader, Write};
use std::path::PathBuf;
use std::process::{Child, Command, Stdio};
use std::sync::{Arc, Mutex};

pub fn run(transform_path: String, paths: Vec<String>, options: Options) -> Result<ExitOutcome, crate::CliError> {
    // Build ignore set.
    let mut ignores = IgnoreSet::new();
    ignores.add_patterns(&options.ignore_pattern);
    for f in &options.ignore_config {
        ignores.add_file(std::path::Path::new(f));
    }
    if options.gitignore {
        let cwd = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
        let gi = cwd.join(".gitignore");
        ignores.add_file(&gi);
    }

    let extensions = options.extensions.as_deref();
    let files = discover::collect(&paths, extensions, &ignores);
    let num_files = files.len();
    if num_files == 0 {
        if !options.silent {
            println!("No files selected, nothing to do.");
        }
        return Ok(ExitOutcome::Code(0));
    }
    if !options.silent {
        println!("Processing {} files...", num_files);
    }

    let cpus = options.cpus.unwrap_or(1);
    let processes = if options.run_in_band {
        1
    } else {
        std::cmp::min(num_files, cpus)
    };
    let chunk_size = if processes > 1 {
        std::cmp::min((num_files + processes - 1) / processes, 50)
    } else {
        num_files
    };
    if !options.silent {
        if options.run_in_band {
            // The JS code does not print this line in runInBand mode.
        } else {
            println!("Spawning {} workers...", processes);
        }
        if options.dry {
            println!("\x1b[32mRunning in dry mode, no files will be written!\x1b[0m");
        }
    }

    let args = vec![transform_path.clone(), if options.babel { "babel".to_string() } else { "no-babel".to_string() }];

    let state = Arc::new(Mutex::new(SharedState {
        counters: FileCounters::default(),
        stats: std::collections::BTreeMap::new(),
        files,
        next_index: 0,
        chunk_size,
        silent: options.silent,
        verbose: options.verbose,
    }));

    let mut workers: Vec<WorkerHandle> = Vec::new();
    for i in 0..processes {
        let child = spawn_worker(&args)?;
        let w = WorkerHandle::new(child, i, state.clone(), options.clone())?;
        workers.push(w);
    }

    for w in workers {
        w.join();
    }

    let state = state.lock().unwrap();
    let mut summary = json!({
        "stats": state.stats,
        "ok": state.counters.ok,
        "error": state.counters.error,
        "nochange": state.counters.nochange,
        "skip": state.counters.skip,
    });
    let _ = summary.as_object_mut();

    if !options.silent {
        println!("All done.");
        print_file_stats(&state.counters);
        print_stats(&state.stats);
    }

    if options.fail_on_error && state.counters.error > 0 {
        return Ok(ExitOutcome::Code(1));
    }

    Ok(ExitOutcome::Code(0))
}

#[derive(Default, Debug)]
pub struct FileCounters {
    pub ok: usize,
    pub error: usize,
    pub nochange: usize,
    pub skip: usize,
}

pub struct SharedState {
    pub counters: FileCounters,
    pub stats: std::collections::BTreeMap<String, i64>,
    pub files: Vec<PathBuf>,
    pub next_index: usize,
    pub chunk_size: usize,
    pub silent: bool,
    pub verbose: u8,
}

pub struct WorkerHandle {
    child: Option<Child>,
    pid_label: String,
    state: Arc<Mutex<SharedState>>,
    options: Options,
    stdout_thread: Option<std::thread::JoinHandle<()>>,
}

impl WorkerHandle {
    fn new(mut child: Child, index: usize, state: Arc<Mutex<SharedState>>, options: Options) -> std::io::Result<Self> {
        let pid_label = format!("worker-{}", index);

        // Send initial config to the worker.
        let config = json!({
            "transform": options.transform,
            "babel": options.babel,
            "parser": options.parser,
            "parserConfig": options.parser_config,
            "print": options.print,
            "dry": options.dry,
            "silent": options.silent,
            "verbose": options.verbose,
            "runInBand": options.run_in_band,
        });
        if let Some(stdin) = child.stdin.as_mut() {
            stdin.write_all(config.to_string().as_bytes())?;
            stdin.write_all(b"\n")?;
            stdin.flush()?;
        }
        Ok(WorkerHandle {
            child: Some(child),
            pid_label,
            state,
            options,
            stdout_thread: None,
        })
    }

    fn join(mut self) {
        let mut child = self.child.take().unwrap();
        let stdout = child.stdout.take().expect("worker stdout");
        let state = self.state.clone();
        let silent = self.options.silent;
        let verbose = self.options.verbose;
        let dry = self.options.dry;

        let join = std::thread::spawn(move || {
            let reader = BufReader::new(stdout);
            for line in reader.lines() {
                let line = match line {
                    Ok(l) => l,
                    Err(_) => break,
                };
                if line.is_empty() {
                    continue;
                }
                let msg: serde_json::Value = match serde_json::from_str(&line) {
                    Ok(v) => v,
                    Err(e) => {
                        if !silent {
                            eprintln!("Worker parse error: {}", e);
                        }
                        continue;
                    }
                };
                let action = msg.get("action").and_then(|v| v.as_str()).unwrap_or("");
                match action {
                    "status" => {
                        let status = msg.get("status").and_then(|v| v.as_str()).unwrap_or("");
                        let m = msg.get("msg").and_then(|v| v.as_str()).unwrap_or("").to_string();
                        let mut s = state.lock().unwrap();
                        match status {
                            "ok" => s.counters.ok += 1,
                            "error" => s.counters.error += 1,
                            "nochange" => s.counters.nochange += 1,
                            "skip" => s.counters.skip += 1,
                            _ => {}
                        }
                        if !silent {
                            drop(s);
                            log_status(status, &m, verbose);
                        }
                    }
                    "update" => {
                        let name = msg.get("name").and_then(|v| v.as_str()).unwrap_or("").to_string();
                        let qty = msg.get("quantity").and_then(|v| v.as_i64()).unwrap_or(1);
                        let mut s = state.lock().unwrap();
                        *s.stats.entry(name).or_insert(0) += qty;
                    }
                    "report" => {
                        let file = msg.get("file").and_then(|v| v.as_str()).unwrap_or("");
                        let m = msg.get("msg").and_then(|v| v.as_str()).unwrap_or("");
                        if !silent {
                            println!("\x1b[44m\x1b[37m REP \x1b[0m\x1b[0m {} {}", file, m);
                        }
                    }
                    "free" => {
                        // Pull next batch and push to worker stdin.
                        let mut s = state.lock().unwrap();
                        let batch: Vec<String> = if s.next_index < s.files.len() {
                            let end = std::cmp::min(s.next_index + s.chunk_size, s.files.len());
                            let slice: Vec<String> = s.files[s.next_index..end]
                                .iter()
                                .map(|p| p.to_string_lossy().to_string())
                                .collect();
                            if !silent && !s.next_index >= s.files.len() {
                                println!(
                                    "Sending {} files to free worker...",
                                    slice.len()
                                );
                            }
                            s.next_index = end;
                            slice
                        } else {
                            Vec::new()
                        };
                        drop(s);
                        // Re-acquire stdin.
                        if let Some(stdin) = child.stdin.as_mut() {
                            let payload = json!({ "files": batch });
                            let _ = stdin.write_all(payload.to_string().as_bytes());
                            let _ = stdin.write_all(b"\n");
                            let _ = stdin.flush();
                        }
                    }
                    "log" => {
                        if !silent {
                            let m = msg.get("msg").and_then(|v| v.as_str()).unwrap_or("");
                            println!("{}", m);
                        }
                    }
                    _ => {}
                }
            }
        });

        // Wait for the worker to exit (it should call process.disconnect
        // after processing all files).
        let _ = child.wait();
        let _ = join.join();
    }
}

fn spawn_worker(args: &[String]) -> std::io::Result<Child> {
    // The bridge script lives at `bridge/transform-host.js` relative to the
    // package root.
    let pkg_root = package_root();
    let bridge = pkg_root.join("bridge").join("transform-host.js");
    let mut cmd = Command::new("node");
    cmd.arg(bridge)
        .arg("--")
        .args(args)
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::inherit());
    cmd.spawn()
}

pub fn package_root() -> PathBuf {
    // The Rust binary lives at <root>/target/.../jscodeshift during
    // development; we locate the package root by walking up until we find
    // a `package.json`.
    let exe = std::env::current_exe().unwrap_or_else(|_| PathBuf::from("."));
    let mut cur = exe.parent().map(|p| p.to_path_buf());
    while let Some(dir) = cur {
        if dir.join("package.json").is_file() {
            return dir;
        }
        cur = dir.parent().map(|p| p.to_path_buf());
    }
    // Fallback: current working directory.
    std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."))
}

pub fn package_version(name: &str) -> String {
    let root = package_root();
    let mut dir = root.clone();
    loop {
        let pkg_path = dir.join("package.json");
        if pkg_path.is_file() {
            if let Ok(text) = std::fs::read_to_string(&pkg_path) {
                if let Ok(value) = serde_json::from_str::<serde_json::Value>(&text) {
                    if value.get("name").and_then(|n| n.as_str()) == Some(name) {
                        if let Some(v) = value.get("version").and_then(|n| n.as_str()) {
                            return v.to_string();
                        }
                    }
                }
            }
        }
        if !dir.pop() {
            break;
        }
    }
    "unknown".to_string()
}

pub fn download_transform(url: &str) -> Result<String, String> {
    // The original Runner uses Node's `http`/`https`. We mirror with a
    // minimal Rust implementation that downloads the body to a temp file
    // whose extension matches the URL path.
    let resp = ureq_fetch(url)?;
    let ext = url_path_ext(url);
    let dir = std::env::temp_dir();
    let pid = std::process::id();
    let path = dir.join(format!("jscodeshift-{}-{:x}{}", pid, rand_suffix(), ext));
    std::fs::write(&path, &resp).map_err(|e| format!("write temp file: {}", e))?;
    Ok(path.to_string_lossy().to_string())
}

fn rand_suffix() -> u64 {
    use std::time::{SystemTime, UNIX_EPOCH};
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_nanos() as u64)
        .unwrap_or(0)
}

fn url_path_ext(url: &str) -> String {
    let path = url.split('?').next().unwrap_or(url);
    let last = path.rsplit('/').next().unwrap_or("");
    let dot = last.rfind('.');
    match dot {
        Some(i) => last[i..].to_string(),
        None => String::new(),
    }
}

fn ureq_fetch(url: &str) -> Result<Vec<u8>, String> {
    // We deliberately avoid pulling in a large HTTP crate; the only thing
    // we ever fetch is a transform file the user explicitly requested.
    // Use `curl` if available, otherwise fail with a clear message.
    let mut cmd = std::process::Command::new("curl");
    cmd.arg("-fsSL").arg(url);
    let out = cmd.output().map_err(|e| format!("curl not available: {}", e))?;
    if !out.status.success() {
        return Err(format!(
            "download failed: {}",
            String::from_utf8_lossy(&out.stderr)
        ));
    }
    Ok(out.stdout)
}

fn print_file_stats(c: &FileCounters) {
    println!("Results: ");
    println!("\x1b[31m{} errors\x1b[0m", c.error);
    println!("\x1b[33m{} unmodified\x1b[0m", c.nochange);
    println!("\x1b[33m{} skipped\x1b[0m", c.skip);
    println!("\x1b[32m{} ok\x1b[0m", c.ok);
}

fn print_stats(stats: &std::collections::BTreeMap<String, i64>) {
    if stats.is_empty() {
        return;
    }
    println!("\x1b[34mStats: \x1b[0m");
    for (name, value) in stats {
        println!("{}: {}", name, value);
    }
}

fn log_status(status: &str, msg: &str, verbose: u8) {
    let line = if msg.ends_with('\n') {
        msg.to_string()
    } else {
        format!("{}\n", msg)
    };
    match status {
        "ok" => {
            if verbose >= 2 {
                print!("\x1b[42m\x1b[37m OKK \x1b[0m\x1b[0m{}", line);
            }
        }
        "nochange" => {
            if verbose >= 1 {
                print!("\x1b[43m\x1b[37m NOC \x1b[0m\x1b[0m{}", line);
            }
        }
        "skip" => {
            if verbose >= 1 {
                print!("\x1b[43m\x1b[37m SKIP \x1b[0m\x1b[0m{}", line);
            }
        }
        "error" => {
            print!("\x1b[41m\x1b[37m ERR \x1b[0m\x1b[0m{}", line);
        }
        _ => {}
    }
    let _ = std::io::stdout().flush();
}"}

